      "ar": "إِنَّمَا يَفْتَرِي الْكَذِبَ الَّذِينَ لَا يُؤْمِنُونَ بِـءَايَٰتِ اللَّهِ وَأُوْلَـٰئِكَ هُمُ الْكَٰذِبُونَ",
