    "declic_frequence": "shakara (être reconnaissant, remercier, racine ش-ك-ر) est le refrain de la sourate : après chaque inventaire de bienfaits revient laʿallakum tashkurūn — « peut-être serez-vous reconnaissants ». Le shukr n'est pas une politesse : c'est la juste réponse de la créature qui reconnaît d'où lui viennent la pluie, le lait, le miel, la mer. Son contraire, le kufr (même racine que « mécréance » : couvrir, occulter), c'est occulter le bienfait, faire comme s'il venait de soi. Toute la sourate oppose ces deux attitudes : reconnaître la source, ou la nier."
